import type { RoadmapItemDto } from "afferent";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";

export function AfferentRoadmapCard({
  item,
}: Readonly<{ item: RoadmapItemDto }>) {
  const { copy, navigation } = useAfferentUi();
  const Link = navigation.Link;
  return (
    <article className="afferent-roadmap-card">
      <h3>
        <Link href={navigation.href.post(item.id)}>{item.title}</Link>
      </h3>
      <p className="afferent-roadmap-card__status">{item.status.label}</p>
      <p className="afferent-roadmap-card__board">{item.board.name}</p>
      <dl className="afferent-roadmap-card__totals">
        <div>
          <dt>Votes</dt>
          <dd>{copy.board.voteCount(item.voteCount)}</dd>
        </div>
        <div>
          <dt>Comments</dt>
          <dd>{copy.board.commentCount(item.commentCount)}</dd>
        </div>
      </dl>
    </article>
  );
}

import type { RoadmapGroupState } from "afferent/react.js";

import { AfferentStateRegion } from "@/components/afferent/core/state-region";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import { AfferentRoadmapCard } from "@/components/afferent/roadmap/roadmap-card";

export function AfferentRoadmapGroup({
  groupKey,
  name,
  group,
}: Readonly<{
  groupKey: "planned" | "in_progress" | "complete";
  name: "Planned" | "In Progress" | "Complete";
  group: RoadmapGroupState;
}>) {
  const { copy } = useAfferentUi();
  return (
    <section
      className="afferent-roadmap-group"
      data-roadmap-group={groupKey}
      aria-labelledby={`afferent-roadmap-${groupKey}`}
    >
      <header>
        <h2 id={`afferent-roadmap-${groupKey}`}>{name}</h2>
        <span aria-label={`${group.items.length} ${name} items`}>
          {group.items.length}
        </span>
      </header>
      {renderGroup(name, group, copy)}
    </section>
  );
}

function renderGroup(
  name: "Planned" | "In Progress" | "Complete",
  group: RoadmapGroupState,
  copy: ReturnType<typeof useAfferentUi>["copy"],
) {
  switch (group.status) {
    case "unsupported": {
      return (
        <AfferentStateRegion title={copy.common.unsupportedHeading}>
          <p>{copy.common.unsupportedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "loading": {
      return <AfferentStateRegion title={copy.roadmap.loadingGroup(name)} />;
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.roadmap.emptyGroup(name)}>
          <p>{copy.roadmap.emptyGroupBody(name)}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion
          title={copy.roadmap.loadErrorHeading(name)}
          tone="error"
          action={
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={group.retry}
            >
              {copy.common.tryLoadingAgain}
            </button>
          }
        >
          <p>{copy.common.queryErrorGuidance}</p>
        </AfferentStateRegion>
      );
    }
    case "ready": {
      return (
        <>
          <ol className="afferent-roadmap-group__list">
            {group.items.map((item) => (
              <li key={item.id}>
                <AfferentRoadmapCard item={item} />
              </li>
            ))}
          </ol>
          {group.canLoadMore ? (
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={group.loadMore}
              disabled={group.isLoadingMore}
              aria-busy={group.isLoadingMore}
            >
              {group.isLoadingMore
                ? copy.roadmap.loadingMore(name)
                : copy.roadmap.loadMore(name)}
            </button>
          ) : null}
        </>
      );
    }
  }
}

"use client";

import { useId, useState } from "react";
import type { BoardDto } from "afferent";
import { useRoadmap } from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import { AfferentRoadmapGroup } from "@/components/afferent/roadmap/roadmap-group";

export function AfferentRoadmapScreen({
  boards = [],
  initialBoardId,
  pageOwner = true,
}: Readonly<{
  boards?: readonly BoardDto[];
  initialBoardId?: BoardDto["id"];
  pageOwner?: boolean;
}>) {
  const { copy } = useAfferentUi();
  const [boardId, setBoardId] = useState<BoardDto["id"] | undefined>(
    initialBoardId,
  );
  const controlId = useId();
  const roadmap = useRoadmap({ boardId });
  const body = (
    <div className="afferent-roadmap" data-afferent-screen="roadmap">
      <header className="afferent-public-header">
        <div>
          <h1>{copy.roadmap.title}</h1>
          <p>{copy.roadmap.description}</p>
        </div>
        {boards.length > 0 ? (
          <label htmlFor={controlId}>
            {copy.roadmap.boardLabel}
            <select
              id={controlId}
              name="roadmap-board"
              value={boardId ?? ""}
              onChange={(event) =>
                setBoardId(
                  event.currentTarget.value
                    ? (event.currentTarget.value as BoardDto["id"])
                    : undefined,
                )
              }
            >
              <option value="">{copy.roadmap.allBoards}</option>
              {boards.map((candidate) => (
                <option key={candidate.id} value={candidate.id}>
                  {candidate.name}
                </option>
              ))}
            </select>
          </label>
        ) : null}
      </header>
      <div className="afferent-roadmap__groups">
        <AfferentRoadmapGroup
          groupKey="planned"
          name="Planned"
          group={roadmap.groups.planned}
        />
        <AfferentRoadmapGroup
          groupKey="in_progress"
          name="In Progress"
          group={roadmap.groups.inProgress}
        />
        <AfferentRoadmapGroup
          groupKey="complete"
          name="Complete"
          group={roadmap.groups.complete}
        />
      </div>
    </div>
  );
  return pageOwner ? <main>{body}</main> : body;
}
